result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "ecs.py", "content": """"Minimal ECS: Position + Velocity components, static wall AABBs,
and a frame() whose system order is the bug under investigation."""

from dataclasses import dataclass, field


# --- Components -----------------------------------------------------------

@dataclass
class Position:
    x: float = 0.0
    y: float = 0.0


@dataclass
class Velocity:
    x: float = 0.0
    y: float = 0.0


@dataclass
class AABB:
    """Static wall box."""
    min_x: float
    min_y: float
    max_x: float
    max_y: float


# --- World ----------------------------------------------------------------

@dataclass
class World:
    positions: dict = field(default_factory=dict)
    velocities: dict = field(default_factory=dict)
    walls: list = field(default_factory=list)
    _next_id: int = 0

    def create_entity(self, position=None, velocity=None):
        eid = self._next_id
        self._next_id += 1
        self.positions[eid] = position if position is not None else Position()
        if velocity is not None:
            self.velocities[eid] = velocity
        return eid

    def add_wall(self, box):
        self.walls.append(box)


# --- Systems --------------------------------------------------------------

def point_overlaps_aabb(p, box):
    return (box.min_x <= p.x <= box.max_x) and (box.min_y <= p.y <= box.max_y)


def movement_system(world, dt=1.0):
    """Integrate velocity into position."""
    for eid, vel in world.velocities.items():
        pos = world.positions[eid]
        pos.x += vel.x * dt
        pos.y += vel.y * dt


def collision_system(world):
    """Clamp dynamic entities out of walls along the axis of least
    penetration; zero the perpendicular velocity component."""
    for eid, vel in world.velocities.items():
        pos = world.positions[eid]
        for box in world.walls:
            if not point_overlaps_aabb(pos, box):
                continue
            pen_left = pos.x - box.min_x          # push out to -x
            pen_right = box.max_x - pos.x         # push out to +x
            pen_bottom = pos.y - box.min_y        # push out to -y
            pen_top = box.max_y - pos.y           # push out to +y
            m = min(pen_left, pen_right, pen_bottom, pen_top)
            if m == pen_left:
                pos.x = box.min_x
                vel.x = min(vel.x, 0.0)
            elif m == pen_right:
                pos.x = box.max_x
                vel.x = max(vel.x, 0.0)
            elif m == pen_bottom:
                pos.y = box.min_y
                vel.y = min(vel.y, 0.0)
            else:
                pos.y = box.max_y
                vel.y = max(vel.y, 0.0)


# --- Frame (BUGGY ORDER: collision response runs before movement) ---------

def frame(world):
    collision_system(world)
    movement_system(world)
